const applyHomeTranslations = (documentText, locale, t) => {
  let html = documentText;
  const replacements = { ...(HOME_TRANSLATIONS[locale] || {}), ...(HOME_DETAIL_TRANSLATIONS[locale] || {}) };
  Object.entries(replacements).sort((a, b) => b[0].length - a[0].length).forEach(([from, to]) => { html = html.replaceAll(from, to); });
  const written = HOME_WRITTEN[locale] || [];
  const sourceQuotes = ['Con Pathway, las explicaciones claras y las clases dinámicas hacen que el francés resulte fácil de entender.', 'Clases amenas y participativas que enriquecen el vocabulario al escuchar distintas formas de expresarse.', 'Paciencia, excelente metodología y un compromiso real con el progreso de cada alumno.', 'Al empezar desde cero, Pathway me acompañó, me hizo participar y se aseguró de que todos avanzáramos.', 'Diálogos en francés, tareas entre clases y apoyo constante para mejorar la pronunciación.', 'En pocas clases empecé a comunicarme con situaciones del día a día y a escuchar francés auténtico.', 'He aprendido mucho y sigo motivada gracias a clases lúdicas que trabajan todas las competencias.', 'En Pathway, el apoyo en español aclara los errores frecuentes de los hispanohablantes y enriquece cada clase.', 'Explicaciones muy claras y una verdadera disposición para ayudar a los alumnos.', 'Mucha paciencia con la pronunciación y clases participativas, dinámicas y sin prisas.', 'Paciencia, pronunciación correcta y explicaciones sobre los matices propios del francés.', 'Atención a cada duda, escrita u oral, con paciencia y una energía que hace las clases amenas.', 'Clases de conversación con temas excelentes; una de mis mejores experiencias aprendiendo francés.', 'El enfoque más práctico, interesante y carismático que he encontrado en dos años estudiando francés.', 'La mejor clase de francés que he tenido: siempre con ganas de enseñar.', 'Gracias a la paciencia de las clases, logré avanzar hasta el nivel A2.'];
  sourceQuotes.forEach((source, index) => { if (written[index]) html = html.replaceAll(source, written[index][0]).replace(new RegExp(`<strong>${['Oscar','La','Carol','Cris','Maximiliano','Jesús','Juanita','Dana','María José','Elisa','Argentina','Gabrielle','Mario','Melissa','Pablo','Mayelly'][index]}</strong>`), `<strong>${written[index][1]}</strong>`); });
  const faq = HOME_FAQ[locale] || [];
  const sourceFaq = [['La evaluación inicial mide tu nivel, disponibilidad y fecha objetivo. A partir de esos datos recomendamos 2, 4 o 6 horas semanales. No necesitas elegir solo.', ''], ['Sí. Las clases principales son privadas y en vivo. Los talleres adicionales pueden reunir a varios alumnos para practicar.', ''], ['No. Pathway es un instituto de idiomas. Nuestro compromiso cubre la preparación y el resultado lingüístico NCLC 7 bajo las condiciones del programa, no una invitación ni una decisión de IRCC.', ''], ['Sí. El pago es mensual, sin permanencia y sin exigir el costo total del programa por adelantado.', '']];
  sourceFaq.forEach(([source], index) => { if (faq[index]) html = html.replaceAll(source, faq[index][1]); });
  const contextPattern = /<p>El francés sigue estando menos utilizado[\s\S]*?nunca una promesa migratoria\.<\/p>/;
  html = html.replace(contextPattern, `<p>${HOME_CONTEXT[locale]}</p>`);
  return html;
};

